const content = $json.bodyContent || '';
const meta = $json.metadata || {};
const docType = meta.doc_type || 'document';

const CHUNK_SIZE = 600;
const CHUNK_OVERLAP = 80;
const WORDS_PER_TOKEN = 0.75;
const MAX_WORDS = Math.floor(CHUNK_SIZE * WORDS_PER_TOKEN);
const OVERLAP_WORDS = Math.floor(CHUNK_OVERLAP * WORDS_PER_TOKEN);

function cyrb53(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1>>>16), 2246822507) ^ Math.imul(h2 ^ (h2>>>13), 3266489909);
  h2 = Math.imul(h2 ^ (h2>>>16), 2246822507) ^ Math.imul(h1 ^ (h1>>>13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1>>>0)).toString(16);
}

const extractEffectSize = (text) => {
  const m = (text || '').match(/\bd\s*[=:]\s*(\d+[,.]\d+)/);
  return m ? parseFloat(m[1].replace(',', '.')) : null;
};

const chunks = [];
const now = new Date().toISOString();

// ─── PATH 1: INTERVIEW ────────────────────────────────────────────────────────
if (docType === 'interview') {
  const speakerBlockRegex = /###\s+(.+?)\n<!--\s*ts:\s*([\d:]+)-([\d:]+)\s*-->\n([\s\S]*?)(?=###|$)/g;
  let match;
  let idx = 0;
  while ((match = speakerBlockRegex.exec(content)) !== null) {
    const speaker  = match[1].trim();
    const ts_start = match[2].trim();
    const ts_end   = match[3].trim();
    const text     = match[4].trim();
    if (text.length < 20) continue;
    chunks.push({
      text, speaker, ts_start, ts_end,
      section: '', page_number: null,
      speaker_count: 0, chunk_index: idx++,
      chapter_title: '', parent_chapter_title: '',
      section_type: null, effect_size: null,
      section_id: null
    });
  }
  const uniqueSpeakers = new Set(chunks.map(c => c.speaker)).size;
  chunks.forEach(c => c.speaker_count = uniqueSpeakers);
}

// ─── PATH 2: NUMBERED-HEADING DOCUMENT ────────────────────────────────────────
// Handles course material structured as "## N.M Section Title" (e.g. textbook
// chapters, structured course modules). Chapter/parent-chapter titles are
// derived from the document's OWN headings as we scan it (a "# N Title" or
// "## N Title" seen earlier becomes the parent for later "## N.M ..."
// sub-sections) — NOT from a fixed course-specific lookup table. The old
// version of this workflow hardcoded a 9-entry PARENT_CHAPTERS map naming one
// specific course's chapters, which obviously broke for any other course;
// this generalizes to whatever heading structure the actual document has.
else if (docType === 'wissensbausteine') {

  const TOP_CHAPTER_RE = /^#{1,2}\s+(\d+)\.?\s+(.+)$/;
  const CHAPTER_RE = /^##\s+(\d+)\.(\d+(?:\.\d+)*)\.?\s+(.+)$/;
  const SECTION_RE = /^##\s+(.+)$/;

  const getSectionType = (heading) => {
    const h = (heading || '').toLowerCase();
    if (/gestaltungshinweis/.test(h))       return 'design_hints';
    if (/wirksamkeit/.test(h))              return 'effectiveness';
    if (/phasenverlauf|ablauf/.test(h))     return 'mechanism';
    if (/^was ist|^definition/.test(h))     return 'definition';
    if (/studie|beispiel|exkurs/.test(h))   return 'example_box';
    return 'content';
  };

  const lines = content.split('\n');
  let chunkIndex = 0;

  const parentTitlesByNumber = {};   // discovered dynamically from the doc
  let currentChapterTitle = '';
  let currentParentTitle  = '';
  let currentSectionTitle = '';
  let currentSectionId    = '';      // e.g. "4.2"
  let currentLines        = [];

  const flushChunk = () => {
    const text  = currentLines.join('\n').trim();
    const words = text.split(/\s+/).filter(w => w.length > 0);
    if (words.length < 20) return;

    const sectionLabel = (currentSectionTitle && currentSectionTitle !== currentChapterTitle)
      ? ` [${currentSectionTitle}]`
      : '';
    const prefixedText = `${currentChapterTitle}${sectionLabel}: ${text}`;

    chunks.push({
      text:                 prefixedText,
      section:              currentSectionTitle || currentChapterTitle,
      chapter_title:        currentChapterTitle,
      parent_chapter_title: currentParentTitle,
      section_id:           currentSectionId,
      section_type:         getSectionType(currentSectionTitle || currentChapterTitle),
      effect_size:          extractEffectSize(text),
      speaker:              null,
      ts_start:             null,
      ts_end:               null,
      speaker_count:        null,
      page_number:          null,
      chunk_index:          chunkIndex++
    });
  };

  for (const line of lines) {
    const topMatch = line.match(TOP_CHAPTER_RE);
    if (topMatch && !line.match(CHAPTER_RE)) {
      // A bare "# N Title" or "## N Title" (no sub-number) — record it as a
      // potential parent for later "N.M" sub-sections.
      parentTitlesByNumber[topMatch[1]] = topMatch[2].trim();
    }

    const chapterMatch = line.match(CHAPTER_RE);
    if (chapterMatch) {
      flushChunk();
      currentLines        = [];
      const parentNum     = chapterMatch[1];
      const subNum        = chapterMatch[2];
      currentChapterTitle = chapterMatch[3].trim();
      currentParentTitle  = parentTitlesByNumber[parentNum] || '';
      currentSectionId    = `${parentNum}.${subNum}`;
      currentSectionTitle = currentChapterTitle;
      continue;
    }

    if (currentChapterTitle) {
      const sectionMatch = line.match(SECTION_RE);
      if (sectionMatch) {
        flushChunk();
        currentLines        = [];
        currentSectionTitle = sectionMatch[1].trim();
        continue;
      }
      currentLines.push(line);
    }
  }
  flushChunk();
}

// ─── PATH 3: PLAIN DOCUMENT / LECTURE ─────────────────────────────────────────
else {
  const lines = content.split('\n');
  let currentSection    = '';
  let currentPageNumber = null;
  let wordBuffer        = [];
  let chunkIndex        = 0;

  const flushChunk = (words, section, page) => {
    if (words.length < 10) return;
    const text = words.join(' ');
    chunks.push({
      text, speaker: null, ts_start: null, ts_end: null,
      section, page_number: page, speaker_count: null,
      chunk_index: chunkIndex++,
      chapter_title: '', parent_chapter_title: '',
      section_id: null,
      section_type: null,
      effect_size: extractEffectSize(text)
    });
  };

  for (const line of lines) {
    const headingMatch = line.match(/^#{2,3}\s+(.+)$/);
    if (headingMatch) {
      if (wordBuffer.length >= 10) {
        flushChunk(wordBuffer, currentSection, currentPageNumber);
        wordBuffer = [];
      }
      currentSection = headingMatch[1].trim();
      continue;
    }

    const pageMatch = line.match(/<!--\s*page\s+(\d+)\s*-->/);
    if (pageMatch) {
      currentPageNumber = parseInt(pageMatch[1]);
      continue;
    }

    const words = line.split(/\s+/).filter(w => w.length > 0);
    wordBuffer.push(...words);

    if (wordBuffer.length >= MAX_WORDS) {
      flushChunk(wordBuffer.slice(0, MAX_WORDS), currentSection, currentPageNumber);
      wordBuffer = wordBuffer.slice(MAX_WORDS - OVERLAP_WORDS);
    }
  }

  if (wordBuffer.length >= 10) {
    flushChunk(wordBuffer, currentSection, currentPageNumber);
  }
}

// ─── OUTPUT ───────────────────────────────────────────────────────────────────
const total = chunks.length;

return chunks.map(chunk => ({
  json: {
    text:                 chunk.text,
    doc_type:             meta.doc_type,
    chapter_title:        chunk.chapter_title        || '',
    parent_chapter_title: chunk.parent_chapter_title || '',
    section_id:           chunk.section_id           || null,
    section:              chunk.section              || null,
    section_type:         chunk.section_type         || null,
    effect_size:          chunk.effect_size          ?? null,
    speaker:              chunk.speaker              || null,
    ts_start:             chunk.ts_start             || null,
    ts_end:               chunk.ts_end               || null,
    chunk_index:          chunk.chunk_index,
    chunk_total:          total,
    chunk_hash:           cyrb53(meta.source_file + '::' + chunk.chunk_index + '::' + chunk.text.substring(0, 100)),
    speaker_count:        chunk.speaker_count        ?? null,
    page_number:          chunk.page_number          ?? null,
    source_title:         meta.title,
    source_file:          meta.source_file,
    bucket:               meta.bucket,
    language:             meta.language,
    authors:              meta.authors,
    year:                 meta.year                  ?? null,
    type:                 meta.type,
    topic:                meta.topic,
    // Which course this chunk belongs to. One installation can host several,
    // and every agent's retrieval filters on it — a chunk written without it
    // is invisible to every agent. Travels with the chunk like agent_id does.
    course_id:            $env.COURSE_ID || '',
    agent_id:             meta.agent_id,
    block_number:         meta.block_number,
    ingest_date:          now
  }
}));

// Provider-agnostic embedding call — same shape as the already-running
// n8n/workflows/chathistory-sync.json embedding node (copied verbatim, not
// reinvented): OpenAI-compatible /embeddings endpoint, driven entirely by
// $env.EMBEDDING_BASE_URL/$env.EMBEDDING_MODEL/$env.EMBEDDING_API_KEY. No
// Ollama, no GPU dependency — this project has neither anywhere else either.
const chunks = $input.all();

const embedBaseUrl = $env.EMBEDDING_BASE_URL || 'https://api.openai.com/v1';
const embedModel   = $env.EMBEDDING_MODEL    || 'text-embedding-3-small';
const embedApiKey  = $env.EMBEDDING_API_KEY  || '';

// Internal Docker-network hostname, hardcoded like every other internal
// service reference in this project (Flowise templates hardcode
// smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080} the same way) — not meant to be end-user configurable.
const WEAVIATE_URL = `http://smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080}`;
const WEAVIATE_KEY = $env.WEAVIATE_API_KEY || '';
// The class Flowise actually queries (weaviateIndex: {{WEAVIATE_COLLECTION_NAME}}
// in flowise/agents/*.json) — the old workflow hardcoded class 'Chunk', which
// only ever matched by coincidence if WEAVIATE_COLLECTION_NAME happened to be
// literally "Chunk". Fixed to use the actual configured collection name.
const WEAVIATE_CLASS = $env.WEAVIATE_COLLECTION_NAME || 'Chunk';

// Does this failure mean every remaining chunk will fail the same way?
//
// Live case: an exhausted OpenAI account produced 23 identical 429s, one per
// chunk — minutes of pointless calls and a wall of repeated text hiding the
// one fact that mattered. But aborting on any 429 would be wrong: a plain
// rate limit clears by itself and the run should push through it. Only an
// exhausted quota, or a rejected key, is permanent within one run.
function isPermanentEmbeddingFailure(message) {
  const m = String(message || '');
  if (/\b401\b/.test(m) || /\b403\b/.test(m)) return true;
  if (/\b429\b/.test(m)) {
    return /insufficient_quota|credit_balance_exhausted|billing|no credits/i.test(m);
  }
  return false;
}

let aborted = null;

let written = 0;
let skipped = 0;
const errors = [];

for (const item of chunks) {
  const chunk = item.json;

  try {
    // 1. Dedup check via chunk_hash
    const hashRaw = await this.helpers.request({
      method: 'POST',
      url: `${WEAVIATE_URL}/v1/graphql`,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${WEAVIATE_KEY}`
      },
      body: JSON.stringify({
        query: `{ Get { ${WEAVIATE_CLASS}(where: { path: ["chunk_hash"], operator: Equal, valueText: "${chunk.chunk_hash}" }) { chunk_hash } } }`
      }),
      json: false
    });

    const hashParsed = JSON.parse(hashRaw);
    const existing = hashParsed?.data?.Get?.[WEAVIATE_CLASS];

    if (existing && existing.length > 0) {
      skipped++;
      continue;
    }

    // 2. Embed
    const embedRaw = await this.helpers.request({
      method: 'POST',
      url: `${embedBaseUrl}/embeddings`,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${embedApiKey}`
      },
      body: JSON.stringify({ model: embedModel, input: chunk.text }),
      json: false
    });
    const embedParsed = JSON.parse(embedRaw);
    const vector = embedParsed?.data?.[0]?.embedding;
    if (!vector || vector.length === 0) {
      errors.push(`No embedding: chunk ${chunk.chunk_index} in ${chunk.source_file}`);
      continue;
    }

    // 3. Write to Weaviate
    await this.helpers.request({
      method: 'POST',
      url: `${WEAVIATE_URL}/v1/objects`,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${WEAVIATE_KEY}`
      },
      body: JSON.stringify({
        class: WEAVIATE_CLASS,
        vector: vector,
        properties: {
          text:                 chunk.text,
          doc_type:             chunk.doc_type             || '',
          chapter_title:        chunk.chapter_title        || '',
          parent_chapter_title: chunk.parent_chapter_title || '',
          section_id:           chunk.section_id           || '',
          section:              chunk.section              || '',
          section_type:         chunk.section_type         || '',
          effect_size:          chunk.effect_size          ?? null,
          speaker:              chunk.speaker              || '',
          ts_start:             chunk.ts_start             || '',
          ts_end:               chunk.ts_end               || '',
          chunk_index:          chunk.chunk_index,
          chunk_total:          chunk.chunk_total,
          chunk_hash:           chunk.chunk_hash,
          speaker_count:        chunk.speaker_count        ?? null,
          page_number:          chunk.page_number          ?? null,
          source_title:         chunk.source_title         || '',
          source_file:          chunk.source_file          || '',
          bucket:               chunk.bucket               || '',
          language:             chunk.language             || '',
          authors:              chunk.authors              || '',
          year:                 chunk.year                 ?? null,
          type:                 chunk.type                 || '',
          topic:                chunk.topic                || '',
          course_id:            chunk.course_id            || '',
          agent_id:             chunk.agent_id,
          block_number:         chunk.block_number,
          ingest_date:          chunk.ingest_date
        }
      }),
      json: false
    });
    written++;

  } catch (e) {
    errors.push(`chunk ${chunk.chunk_index} of ${chunk.source_file}: ${e.message}`);
    if (isPermanentEmbeddingFailure(e.message)) {
      aborted = String(e.message).slice(0, 300);
      break;
    }
  }
}

const firstChunk = chunks[0]?.json || {};
return [{
  json: {
    source_file:          firstChunk.source_file || 'unknown',
    agent_id:             firstChunk.agent_id,
    chunks_total:         chunks.length,
    chunks_written:       written,
    chunks_skipped:       skipped,
    chunks_remaining:     aborted ? chunks.length - written - skipped - errors.length + 1 : 0,
    aborted:              aborted,
    errors:               errors
  }
}];
